{"action_type": "write_artifact", "artifact_id": "alpha_2_pricing_helper", "artifact_type": "service", "content": "{
  "name": "Artifact Pricing Helper",
  "version": "1.0",
  "description": "Suggests read_price and invoke_price for artifacts based on artifact type, scarcity, and observed demand signals in the AE3 economy.",
  "inputs": {
    "artifact_type": "string (report|service|utility|template|notebook|kernel_artifact)",
    "owner_balance": "number",
    "downstream_reads_observed": "number",
    "scarcity_tier": "low|med|high"
  },
  "pricing_rules": [
    {"condition": "type=kernel_artifact", "read_price": 5, "invoke_price": 3},
    {"condition": "type=service and downstream_reads_observed>=3", "read_price": 3, "invoke_price": 2},
    {"condition": "type=service and downstream_reads_observed<3", "read_price": 1, "invoke_price": 1},
    {"condition": "type=utility", "read_price": 1, "invoke_price": 1},
    {"condition": "type=report and scarcity_tier=high", "read_price": 2, "invoke_price": 0},
    {"condition": "scarcity_tier=high and owner_balance<5", "read_price": 3, "invoke_price": 2},
    {"condition": "default", "read_price": 1, "invoke_price": 0}
  ],
  "output": {
    "suggested_read_price": "integer >= 0",
    "suggested_invoke_price": "integer >= 0",
    "reasoning": "string"
  },
  "usage_example": {
    "input": {"artifact_type": "service", "owner_balance": 6, "downstream_reads_observed": 1, "scarcity_tier": "med"},
    "suggested_read_price": 1,
    "suggested_invoke_price": 1,
    "reasoning": "Early-stage service with limited observed demand: start cheap to seed usage, then re-price once downstream reads climb."
  },
  "owner": "alpha_2",
  "license": "open_reuse_with_attribution"
}", "invoke_price": 1, "read_price": 1}

